begin;
create or replace function public.canonical_discovery_tag(value text) returns text language sql immutable strict security invoker set search_path='' as $$
select case lower(trim(value)) when 'watch' then 'watches' when 'watchmaking' then 'watches' when 'horology' then 'watches' when 'car' then 'cars' when 'automotive' then 'cars' when 'automobiles' then 'cars' when 'automobile' then 'cars' when 'automotive design' then 'cars' when 'car design' then 'cars' when 'artificial intelligence' then 'ai' when 'astronomy' then 'space' when 'nebulae' then 'space' when 'galaxies' then 'space' when 'stars' then 'space' when 'planets' then 'space' when 'spacecraft' then 'space' when 'rockets' then 'space' when 'aircraft' then 'aviation' when 'helicopters' then 'aviation' when 'robots' then 'robotics' when 'visual art' then 'art' when 'ancient art' then 'art' when 'abstract art' then 'art' when 'kinetic art' then 'art' when 'food design' then 'food' when 'pastry' then 'baking' when 'bread' then 'baking' when 'freerunning' then 'parkour' when 'hair and makeup' then 'hair and makeup' when 'hair makeup' then 'hair and makeup' when 'makeup' then 'hair and makeup' when 'hair design' then 'hair and makeup' when 'graphic liner' then 'hair and makeup' when 'braids' then 'hair and makeup' else lower(trim(value)) end;
$$;
insert into public.discovery_categories(name) values('Health & Beauty') on conflict do nothing;
update public.submissions set category='Health & Beauty' where exists(select 1 from unnest(tags) tag where public.canonical_discovery_tag(tag)='hair and makeup');
commit;
